    private var buffer: [Int?]
    private var writeIndex = 0
    private var count = 0
    private let capacity: Int
    private var totalWritten = 0
    private var readCursor = 0

    init(capacity: Int) {
        self.capacity = capacity
        self.buffer = Array(repeating: nil, count: capacity)
    }

    func write(_ value: Int) {
        buffer[writeIndex] = value
        writeIndex = (writeIndex + 1) % capacity
        count = Swift.min(count + 1, capacity)
        totalWritten += 1
    }

    private func readAll() -> [Int] {
        guard count > 0 else { return [] }
        let start = count < capacity ? 0 : writeIndex
        var result: [Int] = []
        for i in 0..<count {
            let idx = (start + i) % capacity
            if let value = buffer[idx] {
                result.append(value)
            }
        }
        return result
    }

    func consumeNew() -> [Int] {
        let oldestAvailableSeq = totalWritten - count
        if readCursor < oldestAvailableSeq {
            readCursor = oldestAvailableSeq
        }
        let newCount = totalWritten - readCursor
        readCursor = totalWritten
        guard newCount > 0 else { return [] }
        return Array(readAll().suffix(newCount))
    }
}

