    if (s.isEmpty() || t.isEmpty()) return ""
    val required = HashMap<Char, Int>()
    for (char in t) {
        required[char] = (required[char] ?: 0) + 1
    }
    var missing = t.length
    var left = 0
    var bestStart = 0
    var bestLength = Int.MAX_VALUE
    for (i in s.indices) {
        val char = s[i]
        required[char]?.let { count ->
            if (count > 0) missing--
            required[char] = count - 1
        }
        while (missing == 0) {
            val currentLength = i - left + 1
            if (currentLength < bestLength) {
                bestLength = currentLength
                bestStart = left
            }
            val leftChar = s[left]
            required[leftChar]?.let { count ->
                required[leftChar] = count + 1
                if (count + 1 > 0) missing++
            }
            left++
        }
    }
    return if (bestLength == Int.MAX_VALUE) "" else s.substring(bestStart, bestStart + bestLength)
